"""Detection catalog: every detection carries the metadata the spec requires. Also maps EXISTING rule titles to MITRE/tactic,
and holds the 6-step incident-response playbook per tactic (Validate/Scope/Contain/Eradicate/Recover/Notify). Nothing here auto-executes."""

def D(id, name, sev, mitre, tactic, source, logic, threshold, window, fp, investigate, respond, desc):
    return dict(id=id, name=name, severity=sev, mitre=mitre, tactic=tactic, data_source=source, logic=logic, threshold=threshold,
                window=window, false_positive_risk=fp, investigation=investigate, response=respond, description=desc)

