for _d in CATALOG: MITRE[_d["name"]] = (_d["mitre"].split(" / ")[0], _d["tactic"])

IR = {  # tactic -> six-step response playbook (guidance only; nothing is executed automatically)
 "default": dict(
  validate="Open the alert's raw events and the incident timeline. Confirm user, host, source IP and command line. Compare with baseline and whitelists.",
  scope="Search all hosts/users/IPs seen in the incident (Hunting page: user, IP, hash, command line). Check other endpoints with the same IOC.",
  contain="Consider (manual unless an approved playbook is enabled): block source IP, disable account, isolate endpoint. Prefer least disruptive step first.",
  eradicate="Remove persistence (tasks, services, run keys, accounts), delete malicious files, reset exposed credentials, patch exploited software.",
  recover="Restore from known-good backup if integrity is uncertain, re-enable accounts after reset, monitor closely for 7 days.",
  notify="SOC lead, system owner, and (if data/credentials exposed) security/privacy officer. Record the case ID."),
 "Credential Access": dict(validate="Check 4624/4625/4768/4769/4771/4776 around the time. Did any attempt succeed? From which IP?",
  scope="All accounts targeted by the same IP; all hosts the successful account logged into.", contain="Disable/reset affected accounts, block source IP, enforce MFA.",
  eradicate="Remove any tools/persistence left after the successful logon.", recover="Force password reset, revoke tokens/sessions, review privileged group changes.", notify="Account owners, IAM team, SOC lead."),
 "Defense Evasion": dict(validate="Confirm who changed/cleared logs or disabled protection and whether it was a scheduled maintenance. Check forwarded log copies.",
  scope="Other hosts where the same account disabled protection; time gap in logs.", contain="Re-enable protection; isolate host if unauthorized.", eradicate="Hunt for malware that required the evasion.",
  recover="Rebuild host if integrity unprovable.", notify="SOC lead, endpoint team."),
 "Impact": dict(validate="Verify mass file changes / shadow copy deletion; identify the process.", scope="File shares and backup systems reachable from the host.",
  contain="Isolate host now (approved playbook) and disconnect shares.", eradicate="Stop and remove the process; do not reboot before evidence collection.", recover="Restore from offline backups after clean rebuild.", notify="Incident commander, management, legal/DPO if data affected."),
 "Persistence": dict(validate="Inspect the task/service/run key: binary path, signer, creator account.", scope="Same artifact name/path on other hosts.", contain="Disable the artifact.",
  eradicate="Delete artifact and payload; remove unauthorized accounts.", recover="Re-image if payload was privileged.", notify="System owner, SOC lead."),
}
def playbook_for(tactic): return IR.get(tactic, IR["default"])
def by_name(name): return next((d for d in CATALOG if d["name"] == name), None)
